:root {
  --ah-bg: #010611;
  --ah-panel: rgba(4, 12, 30, .64);
  --ah-panel-strong: rgba(4, 12, 28, .82);
  --ah-border: rgba(108, 221, 255, .24);
  --ah-border-strong: rgba(108, 221, 255, .55);
  --ah-text: rgba(255,255,255,.96);
  --ah-muted: rgba(225,238,255,.76);
  --ah-cyan: #72eaff;
  --ah-blue: #4aa8ff;
  --ah-violet: #9b67ff;
  --ah-pink: #ff5bd7;
  --ah-green: #67f797;
  --ah-amber: #ffd15a;
  --ah-sidebar: 126px;
  --ah-topbar: 82px;
  --ah-shadow: 0 26px 90px rgba(0,0,0,.42);
  --ah-logo-img: url('data:image/png;base64,');
  --ah-cat-img: url('data:image/jpeg;base64,');
  --ah-bg-img: url('data:image/jpeg;base64,');
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body.ah-body {
  margin: 0;
  min-height: 100vh;
  overflow-x: hidden;
  color: var(--ah-text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, sans-serif;
  background:
    radial-gradient(circle at 82% 18%, rgba(81,231,255,.20), transparent 28%),
    radial-gradient(circle at 53% 36%, rgba(151,82,255,.25), transparent 34%),
    radial-gradient(circle at 76% 78%, rgba(255,91,215,.17), transparent 28%),
    linear-gradient(180deg, rgba(1,5,15,.38), rgba(1,5,15,.68)),
    var(--ah-bg-img) center / cover fixed no-repeat,
    #020714;
}
body.ah-body::before {
  content: ""; position: fixed; inset: 0; z-index: 0; pointer-events: none;
  background:
    radial-gradient(circle at 42% 22%, rgba(255,255,255,.85) 0 1px, transparent 2px),
    radial-gradient(circle at 72% 20%, rgba(115,233,255,.75) 0 1px, transparent 2px),
    radial-gradient(circle at 13% 27%, rgba(255,255,255,.65) 0 1px, transparent 2px),
    radial-gradient(circle at 88% 52%, rgba(255,91,213,.62) 0 1px, transparent 2px),
    linear-gradient(90deg, rgba(0,0,0,.58), rgba(0,0,0,.10) 42%, rgba(0,0,0,.08));
}
body.ah-body::after {
  content: ""; position: fixed; inset: 0; z-index: 0; pointer-events: none;
  background: linear-gradient(rgba(255,255,255,.025) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,.018) 1px, transparent 1px);
  background-size: 92px 92px, 92px 92px; opacity: .65;
}
.ah-stars { position: fixed; inset: 0; pointer-events: none; z-index: 0; opacity: .75; background: radial-gradient(circle at 48% 12%, rgba(115,233,255,.18), transparent 18%), radial-gradient(circle at 74% 70%, rgba(255,91,213,.14), transparent 20%); }
a { color: inherit; text-decoration: none; }
button,input { font: inherit; }
svg { width: 1em; height: 1em; fill: none; stroke: currentColor; stroke-width: 1.85; stroke-linecap: round; stroke-linejoin: round; }

.ah-sidebar {
  position: fixed; inset: 0 auto 0 0; width: var(--ah-sidebar); z-index: 20;
  border-right: 1px solid rgba(115,233,255,.24);
  background: linear-gradient(180deg, rgba(1,6,18,.94), rgba(1,6,18,.66));
  backdrop-filter: blur(18px); display: flex; flex-direction: column; align-items: center; padding: 12px 10px 24px;
}
.ah-logo { width: 122px; height: 158px; display: grid; place-items: center; margin-bottom: 20px; position: relative; }
.ah-logo::before { content: ""; position: absolute; inset: 14px 2px 6px; border-radius: 34px; background: radial-gradient(circle, rgba(115,233,255,.16), transparent 66%); filter: blur(12px); }
.ah-logo-mark { position: relative; width: 118px; height: 118px; background-image: var(--ah-logo-img), url('assets/agenhill-logo-v4.png?v=4'); background-position: center; background-size: contain; background-repeat: no-repeat; filter: drop-shadow(0 0 22px rgba(115,233,255,.45)); transition: transform .22s ease, filter .22s ease; }
.ah-logo:hover .ah-logo-mark { transform: scale(1.04) translateY(-2px); filter: drop-shadow(0 0 34px rgba(115,233,255,.65)); }
.ah-side-nav { display: flex; flex-direction: column; gap: 13px; align-items: center; width: 100%; }
.ah-side-nav a { width: 66px; height: 50px; border-radius: 16px; display: grid; place-items: center; color: rgba(236,247,255,.76); font-size: 22px; border: 1px solid transparent; transition: .2s ease; }
.ah-side-nav a:hover,.ah-side-nav .is-active { color: #fff; border-color: rgba(115,233,255,.50); background: linear-gradient(135deg, rgba(74,168,255,.25), rgba(155,102,255,.14)); box-shadow: inset 0 0 18px rgba(115,233,255,.08), 0 0 24px rgba(74,168,255,.16); }

.ah-topbar {
  position: sticky; top: 0; z-index: 15; min-height: var(--ah-topbar); padding-left: var(--ah-sidebar); display: flex; align-items: center; justify-content: space-between; gap: 24px;
  border-bottom: 1px solid rgba(115,233,255,.16); background: rgba(1,6,18,.78); backdrop-filter: blur(18px);
}
.ah-top-nav { display: flex; align-items: center; gap: clamp(18px,3vw,54px); padding-left: clamp(28px,4vw,78px); font-weight: 850; color: rgba(234,242,255,.80); }
.ah-top-nav a { padding: 30px 0 25px; position: relative; white-space: nowrap; }
.ah-top-nav a::after { content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 2px; border-radius: 4px; transform: scaleX(0); background: linear-gradient(90deg,var(--ah-cyan),var(--ah-violet)); transition: .2s ease; }
.ah-top-nav a:hover,.ah-top-nav .is-active { color: var(--ah-cyan); }
.ah-top-nav a:hover::after,.ah-top-nav .is-active::after { transform: scaleX(1); }
.ah-explore { margin-right: clamp(18px,3vw,62px); padding: 13px 20px; border-radius: 16px; border: 1px solid rgba(115,233,255,.48); color: white; font-weight: 950; background: linear-gradient(135deg,rgba(74,168,255,.22),rgba(155,102,255,.14)); box-shadow: 0 0 28px rgba(74,168,255,.20); white-space: nowrap; display: inline-flex; align-items: center; gap: 10px; }
.ah-explore svg { font-size: 19px; color: #72eaff; }

.ah-main { position: relative; z-index: 1; padding-left: var(--ah-sidebar); padding-bottom: 64px; }
.ah-hero {
  width: min(1690px, calc(100vw - var(--ah-sidebar))); margin: 0 auto; min-height: calc(100vh - var(--ah-topbar));
  padding: clamp(56px,5.6vw,84px) clamp(28px,4vw,74px) 26px; display: grid; grid-template-columns: minmax(520px,.92fr) minmax(620px,1.08fr); gap: clamp(24px,3.6vw,64px); align-items: center;
}
.ah-hero-copy { max-width: 715px; position: relative; z-index: 3; }
.ah-pill { display: inline-flex; align-items: center; text-transform: uppercase; letter-spacing: .085em; font-size: 13px; font-weight: 950; color: var(--ah-cyan); padding: 8px 16px; border-radius: 999px; border: 1px solid rgba(115,233,255,.40); background: rgba(3,15,34,.62); box-shadow: inset 0 0 18px rgba(115,233,255,.08),0 0 24px rgba(115,233,255,.08); }
.ah-hero h1 { margin: 26px 0 0; line-height: .91; letter-spacing: -0.075em; font-size: clamp(74px,7.7vw,130px); font-weight: 950; text-shadow: 0 0 18px rgba(255,255,255,.12); }
.ah-hero h1 span,.ah-hero h1 strong { display:block; }
.ah-hero h1 span { color:#fff; filter: drop-shadow(0 0 13px rgba(255,255,255,.22)); }
.ah-hero h1 strong { font-style: normal; background: linear-gradient(90deg,#40c9ff,#6e8cff 48%,#ff5bd5 96%); -webkit-background-clip: text; background-clip: text; color: transparent; filter: drop-shadow(0 0 18px rgba(74,168,255,.34)); }
.ah-by { margin: 19px 0 18px; font-size: 24px; color: rgba(255,255,255,.74); } .ah-by b { color: var(--ah-cyan); }
.ah-status { display: inline-flex; gap: 9px; align-items: center; margin: 0 0 18px; padding: 8px 13px; border-radius: 12px; color: #fff; font-weight: 950; background: linear-gradient(90deg,rgba(74,168,255,.60),rgba(155,102,255,.43)); box-shadow: 0 0 28px rgba(74,168,255,.18); }
.ah-status svg { font-size: 22px; color: #b7ecff; }
.ah-lead { margin:0; max-width:650px; color: var(--ah-muted); font-size:18px; line-height:1.72; text-shadow: 0 2px 18px rgba(0,0,0,.30); }
.ah-actions { display:flex; gap:14px; flex-wrap:wrap; margin-top:26px; }
.ah-btn { display:inline-flex; align-items:center; justify-content:center; min-height:44px; padding:11px 18px; border-radius:14px; color:#fff; font-weight:950; border:1px solid rgba(115,233,255,.28); background:rgba(4,15,35,.62); box-shadow: inset 0 0 18px rgba(115,233,255,.05); }
.ah-btn-main { border-color:rgba(115,233,255,.58); background: linear-gradient(135deg,#70e7ff,#6e8cff 48%,#f35fe4); color:#061028; box-shadow:0 0 32px rgba(115,233,255,.22); }

.ah-hero-art { position:relative; min-height: 640px; pointer-events:none; isolation:isolate; }
.ah-hero-art::before { content:""; position:absolute; inset: 0 0 auto auto; width: 88%; height: 90%; border-radius: 50%; background: radial-gradient(ellipse at 56% 45%, rgba(115,233,255,.16), transparent 47%), radial-gradient(ellipse at 70% 72%, rgba(255,91,213,.18), transparent 43%); filter: blur(18px); z-index:0; }
.ah-cat-visual { position:absolute; inset: -44px -10px -38px -20px; background-image: var(--ah-cat-img), url('assets/agenhill-cat-hero-v4.jpg?v=4'); background-repeat:no-repeat; background-position:center right; background-size: contain; filter: drop-shadow(0 0 50px rgba(82,192,255,.22)) drop-shadow(0 22px 70px rgba(0,0,0,.50)); mask-image: radial-gradient(ellipse at 62% 48%, #000 0 62%, rgba(0,0,0,.72) 70%, transparent 84%); -webkit-mask-image: radial-gradient(ellipse at 62% 48%, #000 0 62%, rgba(0,0,0,.72) 70%, transparent 84%); z-index:1; }

.ah-product-row,.ah-info-strip,.ah-section,.ah-footer { width:min(1450px, calc(100vw - var(--ah-sidebar) - 64px)); margin-left:auto; margin-right:auto; }
.ah-product-row { display:grid; grid-template-columns: repeat(5,minmax(0,1fr)); gap:14px; margin-top:-22px; position:relative; z-index:3; }
.ah-mini-card { min-height:150px; border-radius:22px; border:1px solid var(--ah-border); background:linear-gradient(180deg,rgba(7,18,42,.82),rgba(5,11,28,.70)); box-shadow:var(--ah-shadow); display:flex; flex-direction:column; align-items:center; justify-content:center; text-align:center; gap:9px; transition:.22s ease; position:relative; overflow:hidden; }
.ah-mini-card::before { content:""; position:absolute; inset:0; background: radial-gradient(circle at 50% 0%, rgba(115,233,255,.16), transparent 48%); opacity:.8; }
.ah-mini-card>* { position:relative; } .ah-mini-card:hover { transform:translateY(-5px); border-color: var(--ah-border-strong); box-shadow:0 24px 72px rgba(0,0,0,.42),0 0 28px rgba(115,233,255,.14); }
.ah-mini-icon { width:44px; height:44px; display:grid; place-items:center; font-size:36px; filter:drop-shadow(0 0 16px rgba(115,233,255,.33)); }
.ah-mini-icon svg { width:38px; height:38px; stroke-width:1.75; } .ah-mini-icon.blue { color:#3caeff; } .ah-mini-icon.violet { color:#a06aff; } .ah-mini-icon.green { color:#6df08b; } .ah-mini-icon.cyan { color:#66f3ff; } .ah-mini-icon.pink { color:#e56aff; }
.ah-mini-card h2 { margin:0; font-size:16px; }
.ah-tag { display:inline-flex; align-items:center; justify-content:center; font-size:12px; line-height:1; padding:7px 11px; border-radius:999px; font-style:normal; font-weight:950; }
.ah-green { color:#9cffbe; background:rgba(55,220,114,.15); border:1px solid rgba(91,255,151,.30); } .ah-amber { color:#ffd789; background:rgba(255,190,55,.13); border:1px solid rgba(255,202,83,.28); } .ah-blue { color:#92dfff; background:rgba(74,168,255,.13); border:1px solid rgba(120,210,255,.26); }

.ah-info-strip { margin-top:34px; display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); border:1px solid var(--ah-border); border-radius:26px; overflow:hidden; background:linear-gradient(90deg,rgba(7,18,42,.72),rgba(24,18,56,.56),rgba(7,18,42,.72)); box-shadow:var(--ah-shadow); backdrop-filter: blur(10px); }
.ah-info-strip article { display:flex; align-items:center; gap:20px; padding:28px 34px; border-right:1px solid rgba(115,233,255,.13); } .ah-info-strip article:last-child { border-right:0; }
.ah-info-strip span { width:58px; height:58px; flex:0 0 58px; border-radius:50%; display:grid; place-items:center; background:rgba(74,168,255,.15); border:1px solid rgba(115,233,255,.35); box-shadow:0 0 24px rgba(74,168,255,.20); color:#9eeeff; font-size:24px; }
.ah-info-strip h2 { margin:0 0 6px; color:var(--ah-cyan); font-size:18px; } .ah-info-strip p { margin:0; color:var(--ah-muted); line-height:1.55; }

.ah-section { padding:84px 0 0; } .ah-section-head p,.ah-cabinet-copy p { margin:0 0 10px; color:var(--ah-cyan); text-transform:uppercase; letter-spacing:.09em; font-size:13px; font-weight:950; }
.ah-section-head h2,.ah-cabinet-copy h2 { margin:0; font-size:clamp(36px,4.4vw,64px); line-height:1.03; letter-spacing:-.055em; }
.ah-section-head span,.ah-cabinet-copy span { display:block; margin-top:14px; max-width:880px; color:var(--ah-muted); line-height:1.7; }
.ah-project-grid { margin-top:28px; display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:16px; }
.ah-project-card { min-height:230px; border-radius:24px; border:1px solid var(--ah-border); background:linear-gradient(180deg,rgba(9,20,48,.78),rgba(5,11,28,.72)); padding:26px; box-shadow:var(--ah-shadow); backdrop-filter: blur(9px); }
.ah-project-card b { display:block; font-size:22px; margin-bottom:10px; } .ah-project-card em { display:inline-flex; color:#ffd789; font-style:normal; font-size:12px; font-weight:950; text-transform:uppercase; letter-spacing:.06em; } .ah-project-card p { color:var(--ah-muted); line-height:1.6; } .ah-project-card a { color:var(--ah-cyan); font-weight:900; }
.ah-cabinet-card { display:grid; grid-template-columns:1.1fr .9fr; gap:28px; align-items:center; border-radius:30px; border:1px solid rgba(115,233,255,.30); background:linear-gradient(135deg,rgba(7,18,42,.78),rgba(28,17,58,.52),rgba(5,11,28,.72)); box-shadow:var(--ah-shadow),inset 0 0 60px rgba(115,233,255,.05); padding:clamp(24px,3.5vw,42px); backdrop-filter:blur(10px); }
.ah-login-form { display:grid; grid-template-columns:1fr 1fr auto; align-items:end; gap:12px; } .ah-login-form label { color:rgba(255,255,255,.82); font-weight:850; display:grid; gap:8px; }
.ah-login-form input { width:100%; min-height:48px; color:var(--ah-text); background:rgba(2,8,22,.72); border:1px solid rgba(115,233,255,.28); border-radius:14px; padding:12px 14px; outline:none; } .ah-login-form input:focus { border-color:rgba(115,233,255,.64); box-shadow:0 0 0 4px rgba(115,233,255,.08); }
.ah-login-form button { min-height:48px; border:0; border-radius:14px; padding:12px 18px; font-weight:950; color:#061028; cursor:pointer; background:linear-gradient(135deg,#70e7ff,#6e8cff 48%,#f35fe4); box-shadow:0 0 28px rgba(115,233,255,.20); } .ah-login-error { grid-column:1/-1; margin:0; color:#ff8a8a; font-weight:900; }
.ah-contact-box { margin-top:28px; display:flex; flex-wrap:wrap; gap:14px; padding:22px; border-radius:22px; border:1px solid var(--ah-border); background:rgba(5,12,28,.64); backdrop-filter:blur(8px); } .ah-contact-box a { padding:13px 17px; border-radius:14px; border:1px solid rgba(115,233,255,.26); background:rgba(4,15,35,.64); font-weight:900; }
.ah-footer { position:relative; z-index:1; padding:34px 0 44px; color:rgba(224,236,255,.76); display:flex; justify-content:space-between; gap:30px; border-top:1px solid rgba(115,233,255,.12); margin-top:74px; } .ah-footer nav { display:flex; gap:18px; flex-wrap:wrap; justify-content:flex-end; } .ah-footer a:hover { color:var(--ah-cyan); }

@media (max-width:1280px) { .ah-hero { grid-template-columns:1fr; min-height:auto; } .ah-hero-copy { max-width:760px; } .ah-hero-art { min-height:580px; } .ah-cat-visual { inset:-20px 0 -20px 0; background-position:center; } .ah-product-row { grid-template-columns:repeat(2,minmax(0,1fr)); margin-top:18px; } .ah-project-grid { grid-template-columns:repeat(2,minmax(0,1fr)); } .ah-cabinet-card { grid-template-columns:1fr; } .ah-login-form { grid-template-columns:1fr 1fr; } .ah-login-form button,.ah-login-error { grid-column:1/-1; } }
@media (max-width:920px) { :root { --ah-sidebar:0px; } .ah-sidebar { display:none; } .ah-topbar { padding-left:0; flex-wrap:wrap; min-height:auto; padding:14px 16px; } .ah-top-nav { overflow-x:auto; gap:22px; padding-left:0; width:100%; } .ah-top-nav a { padding:10px 0 12px; white-space:nowrap; } .ah-explore { margin-right:0; } .ah-main { padding-left:0; } .ah-hero { width:100%; padding:46px 18px 24px; grid-template-columns:1fr; } .ah-hero h1 { font-size:clamp(58px,18vw,92px); } .ah-hero-art { min-height:440px; } .ah-product-row,.ah-info-strip,.ah-section,.ah-footer { width:calc(100vw - 34px); } .ah-product-row { grid-template-columns:1fr; } .ah-info-strip { grid-template-columns:1fr; } .ah-info-strip article { border-right:0; border-bottom:1px solid rgba(115,233,255,.13); } .ah-project-grid { grid-template-columns:1fr; } .ah-login-form { grid-template-columns:1fr; } .ah-footer { flex-direction:column; } .ah-footer nav { justify-content:flex-start; } }
